alto = \relative c' { \global \set midiInstrument = "alto sax" s8 | b4\pp cis8 dis4 cis8 | b4 cis8 dis4 cis8 |b4 dis8 cis4 dis8 | e4 fis8 gis [a b] | e,4 fis8 gis4. | dis4 e8 fis4 b,8 d4.~ d4 d8 | cis4. \bar "||" e4 fis | gis2 e4 a | gis2 e4 fis | gis e e a | gis2 e4 e | e2 e4 e | cis2 b4 b | b2 b4 e | e2 e4 e | fis (gis) a e | cis2 b4 b | b1 \bar "|." }
tenor = \relative c' { \global \set midiInstrument = "tenor sax" s8 | gis4\pp a8 b4 a8 | gis4 a8 b4 a8 | gis4. fis4 a8 | gis4 b8 e fis gis | cis,4 dis8 e4. | b4 cis8 dis4 e8 | a,4. d4 b8 | a4. \bar "||" r2 | r2 gis4 a | b2 e4 cis | b2 gis4 a | b4 b cis cis | b2 gis4 cis | cis (a) gis fis | gis4. (a8) b4 gis | cis2 b4 cis |d2 cis4 cis | a2 gis4 fis | gis1 \bar "|." }
bass = \relative c { \global \set midiInstrument = "baritone sax" s8 | e4 dis8 cis4 dis8 | e4 dis8 cis4 dis8 | e2. | e4.~ e8 r8 r | a4. gis4 e8 | gis4. fis4 e8 | d4.~ d4 e8 a4. \bar "||" r2 | r2 e4 fis | gis2 cis4 a | gis2 e4 fis | gis gis cis a | gis2 cis,4 cis | fis,2 gis4 b | e2 e4 e4 | a,2 e'4 cis | b2 a4 cis | fis2 b,4 b | e1 \bar "|." }
verse = \lyricmode { " " Here we come a -- was -- sail -- ing a -- mong the leaves so green; "" Here we come a -- wan -- der -- ing, so fair to be seen.
Love and joy come to you, and to you your was -- sail too, and God bless you, and send you a hap -- py New Year, and God send you a hap -- py New Year. }
